#include <iostream>
using namespace std; 

// define the Test class
class Test {
    public:
        int number;

        void display_number() {
            cout << this->number << endl;
        }
};

int main() {

    Test t1;
    t1.number = 3;
    Test t2;
    t2.number = 5;

    t1.display_number();

    return 0;
}
